import {faultCatalog,energyFaultScore} from './energy-faults.mjs';
export function createEnergyResults(storage){const key='mecanica.energy-diagnostics.v1';let rows=[],warning='';
 try{const saved=JSON.parse(storage.getItem(key)||'[]');if(!Array.isArray(saved))throw Error();rows=saved.filter(r=>r&&typeof r.id==='string'&&faultCatalog[r.lab]&&['basic','combined','intermittent'].includes(r.level)&&Number.isFinite(r.score)&&r.score>=0&&r.score<=100&&Array.isArray(r.faults)&&r.faults.length&&r.faults.every(f=>faultCatalog[r.lab].some(x=>x.id===f))&&Array.isArray(r.events)&&Number.isFinite(Date.parse(r.date))).slice(-200);}catch{warning='No se pudo leer el historial. Los resultados nuevos se conservarán en esta sesión.';}
 return {all:()=>structuredClone(rows),warning:()=>warning,save(s){if(!s.done||rows.some(r=>r.id===s.id))return;rows.push({id:s.id,date:s.finishedAt,lab:s.lab,level:s.level,score:energyFaultScore(s),reviewTarget:s.reviewTarget||null,errors:s.errors,hints:s.hints,faults:[...s.faults],events:structuredClone(s.events)});rows=rows.slice(-200);try{storage.setItem(key,JSON.stringify(rows));}catch{warning='No se pudo guardar en este navegador. Los resultados están disponibles solo en esta sesión.';}},stats(){return Object.entries(faultCatalog).flatMap(([lab,fs])=>fs.map(f=>{const cases=rows.filter(r=>r.lab===lab&&r.faults.includes(f.id));let errors=0,hints=0;for(const r of cases)for(const e of r.events){if(!e||!Array.isArray(e.targets)||!e.targets.includes(f.id))continue;if(e.wrong)errors++;if(e.action==='hint')hints++;}return {lab,id:f.id,label:f.label,n:cases.length,errors,hints,rate:cases.length?errors/cases.length:0};})).filter(s=>s.n).sort((a,b)=>b.rate-a.rate||b.hints-a.hints);}};
}
